{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_scorecard AS WITH latest_allocation AS ( SELECT branch_code, MAX(order_date) AS latest_order_date FROM snitch_db.maplemonk.fresh_mix_score GROUP BY branch_code ), base AS ( SELECT f.* FROM snitch_db.maplemonk.fresh_mix_score f INNER JOIN latest_allocation la ON f.branch_code = la.branch_code AND f.order_date = la.latest_order_date ), rolled AS ( SELECT branch_code, order_date, SUM(alloc_option_count) AS total_actual_options, COUNT(*) AS total_combos, SUM(mix_deviation * effective_weight) / NULLIF(SUM(effective_weight), 0) AS weighted_mix_deviation, MAX(warehouse_constrained_flag) AS warehouse_constrained_flag, CASE WHEN SUM(alloc_option_count) < 3 THEN \'Insufficient Volume\' WHEN (SUM(mix_deviation * effective_weight) / NULLIF(SUM(effective_weight), 0)) <= 0.15 THEN \'Perfect\' WHEN (SUM(mix_deviation * effective_weight) / NULLIF(SUM(effective_weight), 0)) <= 0.30 THEN \'Okay\' ELSE \'Poor\' END AS composite_score FROM base GROUP BY branch_code, order_date ), with_zone_priority AS ( SELECT r.*, COALESCE(z.zone, \'SOUTH\') AS zone, COALESCE(pt.store_priority_tier, \'Medium Priority\') AS store_priority_tier, COALESCE(pt.current_month_target, 0) AS current_month_target FROM rolled r LEFT JOIN snitch_db.maplemonk.store_zone_map z ON r.branch_code = z.branch_code LEFT JOIN snitch_db.maplemonk.store_priority_tier pt ON r.branch_code = pt.branch_code ), top_offender AS ( SELECT branch_code, order_date, CASE WHEN UPPER(TRIM(category)) IN (\'DENIM\', \'DENIMS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(category)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CASUAL TROUSER\', \'CASUAL TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(category)) IN (\'CARGO\', \'CARGO PANTS\') THEN \'CARGO PANTS\' ELSE UPPER(TRIM(category)) END AS top_offending_category, style AS top_offending_style, meta1 AS top_offending_meta1, meta2 AS top_offending_meta2, meta3 AS top_offending_meta3, mix_deviation AS top_offending_deviation, achievable_target_pct AS target_allocation_pct, alloc_mix_pct AS actual_allocation_pct FROM ( SELECT branch_code, order_date, category, style, meta1, meta2, meta3, mix_deviation, achievable_target_pct, alloc_mix_pct, ROW_NUMBER() OVER (PARTITION BY branch_code, order_date ORDER BY mix_deviation DESC) AS rn FROM base ) WHERE rn = 1 ), category_network_share_thresholds AS ( SELECT UPPER(TRIM(category)) AS category, PERCENTILE_CONT(0.20) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE)) AS p20_price, PERCENTILE_CONT(0.70) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE)) AS p70_price, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE)) AS p90_price FROM snitch_db.maplemonk.availability_master_v2 WHERE COALESCE(CURRENT_SLASHED_PRICE, PRICE) > 0 AND category IS NOT NULL GROUP BY UPPER(TRIM(category)) ), normalized_store_fact AS ( SELECT f.branch_code::VARCHAR AS branch_code, f.selling_price, f.suborder_quantity, CASE WHEN UPPER(TRIM(f.category)) IN (\'DENIM\', \'DENIMS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(f.category)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CASUAL TROUSER\', \'CASUAL TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(f.category)) IN (\'CARGO\', \'CARGO PANTS\') THEN \'CARGO PANTS\' ELSE UPPER(TRIM(f.category)) END AS category FROM snitch_db.maplemonk.store_fact_items_offline f WHERE f.suborder_quantity > 0 AND f.selling_price > 0 AND f.category IS NOT NULL ), store_historical_asp AS ( SELECT nf.branch_code, nf.category, SUM(nf.selling_price) / NULLIF(SUM(nf.suborder_quantity), 0) AS store_category_asp FROM normalized_store_fact nf GROUP BY nf.branch_code, nf.category ), allocated_top_category_prices AS ( SELECT a.branch_code::VARCHAR AS branch_code, a.order_date, CASE WHEN UPPER(TRIM(a.category)) IN (\'DENIM\', \'DENIMS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(a.category)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CASUAL TROUSER\', \'CASUAL TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(a.category)) IN (\'CARGO\', \'CARGO PANTS\') THEN \'CARGO PANTS\' ELSE UPPER(TRIM(a.category)) END AS category, SUM(a.actual_qty * COALESCE(v.CURRENT_SLASHED_PRICE, v.PRICE)) / NULLIF(SUM(a.actual_qty), 0) AS avg_alloted_price FROM snitch_db.maplemonk.fresh_allocation_tagged a LEFT JOIN snitch_db.maplemonk.availability_master_v2 v ON a.sku_group = v.sku_group GROUP BY a.branch_code::VARCHAR, a.order_date, CASE WHEN UPPER(TRIM(a.category)) IN (\'DENIM\', \'DENIMS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(a.category)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CASUAL TROUSER\', \'CASUAL TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(a.category)) IN (\'CARGO\', \'CARGO PANTS\') THEN \'CARGO PANTS\' ELSE UPPER(TRIM(a.category)) END ), price_fit_summary AS ( SELECT t.branch_code, t.order_date, t.top_offending_category, asp.store_category_asp, p.avg_alloted_price, CASE WHEN asp.store_category_asp IS NULL THEN \'Mid-Range (₹\' || ROUND(c.p20_price) || \' - ₹\' || ROUND(c.p70_price) || \')\' WHEN asp.store_category_asp < c.p20_price THEN \'Budget (< ₹\' || ROUND(c.p20_price) || \')\' WHEN asp.store_category_asp BETWEEN c.p20_price AND c.p70_price THEN \'Mid-Range (₹\' || ROUND(c.p20_price) || \' - ₹\' || ROUND(c.p70_price) || \')\' WHEN asp.store_category_asp BETWEEN c.p70_price AND c.p90_price THEN \'Premium (₹\' || ROUND(c.p70_price) || \' - ₹\' || ROUND(c.p90_price) || \')\' ELSE \'Super Premium (> ₹\' || ROUND(c.p90_price) || \')\' END AS store_ideal_price_bucket, CASE WHEN p.avg_alloted_price IS NULL THEN \'Mid-Range (₹\' || ROUND(c.p20_price) || \' - ₹\' || ROUND(c.p70_price) || \')\' WHEN p.avg_alloted_price < c.p20_price THEN \'Budget (< ₹\' || ROUND(c.p20_price) || \')\' WHEN p.avg_alloted_price BETWEEN c.p20_price AND c.p70_price THEN \'Mid-Range (₹\' || ROUND(c.p20_price) || \' - ₹\' || ROUND(c.p70_price) || \')\' WHEN p.avg_alloted_price BETWEEN c.p70_price AND c.p90_price THEN \'Premium (₹\' || ROUND(c.p70_price) || \' - ₹\' || ROUND(c.p90_price) || \')\' ELSE \'Super Premium (> ₹\' || ROUND(c.p90_price) || \')\' END AS alloted_price_bucket, CASE WHEN asp.store_category_asp IS NULL THEN 2 WHEN asp.store_category_asp < c.p20_price THEN 1 WHEN asp.store_category_asp BETWEEN c.p20_price AND c.p70_price THEN 2 WHEN asp.store_category_asp BETWEEN c.p70_price AND c.p90_price THEN 3 ELSE 4 END AS ideal_tier_idx, CASE WHEN p.avg_alloted_price IS NULL THEN 2 WHEN p.avg_alloted_price < c.p20_price THEN 1 WHEN p.avg_alloted_price BETWEEN c.p20_price AND c.p70_price THEN 2 WHEN p.avg_alloted_price BETWEEN c.p70_price AND c.p90_price THEN 3 ELSE 4 END AS allotted_tier_idx FROM top_offender t LEFT JOIN category_network_share_thresholds c ON t.top_offending_category = c.category LEFT JOIN store_historical_asp asp ON t.branch_code = asp.branch_code AND t.top_offending_category = asp.category LEFT JOIN allocated_top_category_prices p ON t.branch_code = p.branch_code AND t.order_date = p.order_date AND t.top_offending_category = p.category ), evaluated_price_fit AS ( SELECT pf.*, CASE WHEN pf.ideal_tier_idx = pf.allotted_tier_idx THEN \'Ideal\' WHEN ABS(pf.ideal_tier_idx - pf.allotted_tier_idx) = 1 THEN \'Okay\' ELSE \'Not Okay\' END AS price_score FROM price_fit_summary pf ), final AS ( SELECT w.*, mf.\"STORE NAME\" AS branch_name, t.top_offending_category, t.top_offending_style, t.top_offending_meta1, t.top_offending_meta2, t.top_offending_meta3, t.top_offending_deviation, t.target_allocation_pct, t.actual_allocation_pct, COALESCE(pf.store_ideal_price_bucket, \'Mid-Range\') AS store_ideal_price_bucket, COALESCE(pf.alloted_price_bucket, \'Mid-Range\') AS alloted_price_bucket, COALESCE(pf.price_score, \'Okay\') AS price_score FROM with_zone_priority w LEFT JOIN snitch_db.maplemonk.master_file mf ON w.branch_code::VARCHAR = mf.\"STORE CODE\"::VARCHAR LEFT JOIN top_offender t ON w.branch_code = t.branch_code AND w.order_date = t.order_date LEFT JOIN evaluated_price_fit pf ON w.branch_code = pf.branch_code AND w.order_date = pf.order_date ) SELECT branch_code, branch_name, zone, order_date, total_actual_options, total_combos, warehouse_constrained_flag, weighted_mix_deviation, composite_score, CASE WHEN composite_score = \'Insufficient Volume\' THEN \'Batch Size Too Small (< 3 Options)\' WHEN actual_allocation_pct > (target_allocation_pct + 0.15) THEN \'Over-Allocated\' WHEN actual_allocation_pct < (target_allocation_pct - 0.15) THEN \'Under-Allocated\' ELSE \'Balanced Allocation\' END AS allocation_remark, top_offending_category, top_offending_style, top_offending_meta1, top_offending_meta2, top_offending_meta3, target_allocation_pct, actual_allocation_pct, top_offending_deviation, store_ideal_price_bucket, alloted_price_bucket, price_score, store_priority_tier, current_month_target, CASE WHEN composite_score NOT IN (\'Perfect\', \'Okay\', \'Poor\') THEN composite_score WHEN composite_score = \'Poor\' AND store_priority_tier = \'High Priority\' THEN \'Critical\' WHEN composite_score = \'Poor\' AND store_priority_tier = \'Medium Priority\' THEN \'Concern\' WHEN composite_score = \'Poor\' AND store_priority_tier = \'Low Priority\' THEN \'Low Concern\' WHEN composite_score = \'Okay\' AND store_priority_tier = \'High Priority\' THEN \'Watch\' ELSE composite_score END AS severity_adjusted_score, RANK() OVER ( PARTITION BY store_priority_tier ORDER BY CASE WHEN composite_score IN (\'Perfect\',\'Okay\',\'Poor\') THEN weighted_mix_deviation END ASC NULLS LAST ) AS store_rank_within_tier FROM final ORDER BY branch_code;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            